int f(vector<int> a, int k) {
    int s = 0;
    for (int i = 0; i < k; i++) s += a[i];
    int best = s;
    for (int i = k; i < a.size(); i++) {
        s += a[i] - a[i - k];
        best = max(best, s);
    }
    return best;
}

