def f(a):
    take, skip = 0, 0
    for x in a:
        take, skip = skip + x, max(take, skip)
    return max(take, skip)

code.cpp:
int f(vector<int> a) {
    int take = 0, skip = 0;
    for (int x : a) {
        int t = skip + x;
        skip = max(take, skip);
        take = t;
    }
    return max(take, skip);
}

code.java:
static int f(int[] a) {
    int take = 0, skip = 0;
    for (int x : a) {
        int t = skip + x;
        skip = Math.max(take, skip);
        take = t;
    }
    return Math.max(take, skip);
}
